import {shouldContinueToolLoop, accumulateUsage} from './orchestratorHelpers.js';
import type {ToolRegistry} from './tools/registry.js';
import type {ToolCall, UsageMetadata} from '../types/ai.js';

// All three conditions matter; dropping the registry check spins the tool loop.

const A_TOOL: ToolCall[] = [{id: 't1', name: 'lookup', input: {}}];
const REGISTRY = {} as ToolRegistry;

describe('shouldContinueToolLoop', () => {
  it('continues when the model requested a tool and a registry can run it', () => {
    expect(shouldContinueToolLoop('tool_use', A_TOOL, REGISTRY)).toBe(true);
  });

  it('stops when no registry is configured, whatever the model asked for', () => {
    expect(shouldContinueToolLoop('tool_use', A_TOOL, undefined)).toBe(false);
  });

  it('stops when the model named no tool', () => {
    expect(shouldContinueToolLoop('tool_use', [], REGISTRY)).toBe(false);
  });

  it('stops when the model finished for a reason other than tool use', () => {
    expect(shouldContinueToolLoop('end_turn', A_TOOL, REGISTRY)).toBe(false);
  });
});

describe('accumulateUsage', () => {
  it('returns the new usage when nothing is accumulated yet', () => {
    const usage: UsageMetadata = {inputTokens: 10, outputTokens: 5, totalTokens: 15};
    expect(accumulateUsage(undefined, usage)).toEqual(usage);
  });

  it('sums both usages when both are defined', () => {
    const accumulated: UsageMetadata = {inputTokens: 10, outputTokens: 5, totalTokens: 15};
    const newUsage: UsageMetadata = {inputTokens: 20, outputTokens: 3, totalTokens: 23};
    expect(accumulateUsage(accumulated, newUsage)).toEqual({
      inputTokens: 30,
      outputTokens: 8,
      totalTokens: 38,
    });
  });

  it('skips the new usage when it is undefined', () => {
    const accumulated: UsageMetadata = {inputTokens: 10, outputTokens: 5, totalTokens: 15};
    expect(accumulateUsage(accumulated, undefined)).toEqual(accumulated);
  });

  it('returns undefined when both are undefined', () => {
    expect(accumulateUsage(undefined, undefined)).toBeUndefined();
  });
});

